import{_ as a,o,c as t,a6 as d}from"./chunks/framework.B_q3ZJNF.js";const f=JSON.parse('{"title":"练习梯子","description":"","frontmatter":{},"headers":[],"relativePath":"mini-git-ts-course/exercises.md","filePath":"mini-git-ts-course/docs/exercises.md"}'),r={name:"mini-git-ts-course/exercises.md"};function s(c,e,i,l,m,n){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="练习梯子" tabindex="-1">练习梯子 <a class="header-anchor" href="#练习梯子" aria-label="Permalink to &quot;练习梯子&quot;">​</a></h1><p>八级练习加一个毕业任务,全部长在你已学过的机制上——每级需要的每个原语,正文都示范过。顺序即依赖:对象 → 树 → 提交 → 暂存区 → 引用 → diff → 合并 → 协议。做完一级跑 <code>pnpm test</code>,旧测试必须全绿。</p><h2 id="第-1-级-·-cat-file-s" tabindex="-1">第 1 级 · cat-file -s <a class="header-anchor" href="#第-1-级-·-cat-file-s" aria-label="Permalink to &quot;第 1 级 · cat-file -s&quot;">​</a></h2><p>给 <code>mini-git cat-file</code> 加 <code>-s</code>:只打印对象的字节数(对象体的长度,不含对象头)。空文件应得 0,<code>hello world\\n</code> 应得 12。</p><details><summary>要点</summary><p><code>readObject</code> 已返回 <code>{ type, body }</code>,<code>body.length</code> 就是答案;麻烦只在参数解析多认一个开关。回查<a href="./02-content-addressed-store.html">第 2 章</a>的 cat-file 实现与对象头结构。</p></details><h2 id="第-2-级-·-ls-tree" tabindex="-1">第 2 级 · ls-tree <a class="header-anchor" href="#第-2-级-·-ls-tree" aria-label="Permalink to &quot;第 2 级 · ls-tree&quot;">​</a></h2><p>实现 <code>mini-git ls-tree &lt;tree哈希&gt;</code>:一行一条列出某棵 tree 的条目(模式、类型、哈希、名字)。嵌套目录只列本层,不递归。</p><details><summary>要点</summary><p><code>parseTree</code> 拿条目数组,<code>renderTree</code> 已经会渲染——它此刻只被 cat-file -p 内部调用;把渲染抽出来接一条命令即可。类型判定(<code>40000</code> → tree)回查<a href="./03-tree-snapshots.html">第 3 章</a>。</p></details><h2 id="第-3-级-·-log-oneline" tabindex="-1">第 3 级 · log --oneline <a class="header-anchor" href="#第-3-级-·-log-oneline" aria-label="Permalink to &quot;第 3 级 · log --oneline&quot;">​</a></h2><p>给 log 加 <code>--oneline</code>:每笔提交只打一行——哈希前 7 位加消息首行。短哈希仅用于显示,内部解析仍只认 40 位全名。</p><details><summary>要点</summary><p><code>renderLogEntry</code> 已经产出整段卡片;另写一个短渲染函数,遍历 <code>logWalk</code> 的结果。7 位截断是显示层约定,回查<a href="./04-commit-dag.html">第 4 章</a>的 log 渲染与第 2 章「只认全名」的口径。</p></details><h2 id="第-4-级-·-status-short" tabindex="-1">第 4 级 · status --short <a class="header-anchor" href="#第-4-级-·-status-short" aria-label="Permalink to &quot;第 4 级 · status --short&quot;">​</a></h2><p>给 status 加 <code>--short</code>:输出两列状态码加路径(如 <code>M </code>、<code> M</code>、<code>??</code>、<code>D </code>),与真 git <code>status --short</code> 的两列语义对齐。</p><details><summary>要点</summary><p><code>classifyStatus</code> 已产出四类判定;剩下是四类 → 两列码的映射表。第 1 章用真 git 演示过两列码的形状,第 5 章有三态对比的正本。对拍:同一目录状态跑 <code>git -c core.autocrlf=false status --short</code> 比对。</p></details><h2 id="第-5-级-·-branch-d" tabindex="-1">第 5 级 · branch -d <a class="header-anchor" href="#第-5-级-·-branch-d" aria-label="Permalink to &quot;第 5 级 · branch -d&quot;">​</a></h2><p>实现 <code>mini-git branch -d &lt;名字&gt;</code>:删除分支。当前分支不许删;要删的分支不存在时报可读的错。</p><details><summary>要点</summary><p>分支只是 <code>refs/heads/</code> 下的小文件——删除就是删文件。判断「当前分支」用 <code>readHead</code> 的符号引用形状。回查<a href="./06-refs-branches.html">第 6 章</a>。</p></details><h2 id="第-6-级-·-diff-的-u-参数" tabindex="-1">第 6 级 · diff 的 -U 参数 <a class="header-anchor" href="#第-6-级-·-diff-的-u-参数" aria-label="Permalink to &quot;第 6 级 · diff 的 -U 参数&quot;">​</a></h2><p>给 diff 加 <code>-U &lt;n&gt;</code>:上下文行数可调(默认 3)。上下文变窄,相邻改动组的合并判定跟着变——先在纸上预测 <code>-U 1</code> 时第 7 章的「间隔 6 行合并」金样会怎样,再跑。</p><details><summary>要点</summary><p><code>CONTEXT_LINES</code> 目前是常量;把它变成 <code>renderUnified</code> 的参数,合并判断 <code>gap &lt;= 2 * CONTEXT_LINES</code> 的算术原样搬。间隔 6 行的用例在 <code>-U 1</code> 下窗口 3+3 变 1+1,该拆开。回查<a href="./07-line-diff.html">第 7 章</a>的 hunk 合并。</p></details><h2 id="第-7-级-·-merge-no-ff" tabindex="-1">第 7 级 · merge --no-ff <a class="header-anchor" href="#第-7-级-·-merge-no-ff" aria-label="Permalink to &quot;第 7 级 · merge --no-ff&quot;">​</a></h2><p>给 merge 加 <code>--no-ff</code>:即便可以 fast-forward 也强制走真合并,产一笔双父提交(第二父指向被合分支)。</p><details><summary>要点</summary><p><code>mergeCommits</code> 的 ff 短路在头两行;加一个开关跳过短路、直接走合并路径即可,base 就是另一方本身。回查<a href="./08-merge-base.html">第 8 章</a>的 ff 等价与<a href="./09-three-way-merge.html">第 9 章</a>的双父构造。</p></details><h2 id="第-8-级-·-ls-remote-heads-以外的过滤" tabindex="-1">第 8 级 · ls-remote --heads 以外的过滤 <a class="header-anchor" href="#第-8-级-·-ls-remote-heads-以外的过滤" aria-label="Permalink to &quot;第 8 级 · ls-remote --heads 以外的过滤&quot;">​</a></h2><p>给 ls-remote 加 <code>--count &lt;n&gt;</code>:只显示前 n 条引用(按现有顺序,HEAD 第一)。</p><details><summary>要点</summary><p><code>discoverRefs</code> 返回数组,显示层已有一个过滤(零号占位行);再加一层 slice 即可。注意别把 flush 帧之类协议层概念混进显示层。回查<a href="./10-wire-protocol.html">第 10 章</a>。</p></details><h2 id="毕业任务-·-mini-git-rm" tabindex="-1">毕业任务 · mini-git rm <a class="header-anchor" href="#毕业任务-·-mini-git-rm" aria-label="Permalink to &quot;毕业任务 · mini-git rm&quot;">​</a></h2><p>实现 <code>mini-git rm &lt;路径&gt;</code>:从暂存区清单删除该路径的登记,让下一次 commit 不再包含它;status 此刻应报出「已暂存的删除」。不删工作区文件(那是 <code>rm --cached</code> 的口径,正文只承诺这一种)。</p><p>完成标准:</p><ol><li><code>pnpm test</code> 全绿,且为 rm 新增的行为测试先红后绿;</li><li>提交后,真 git 在同一仓库跑 <code>git -c core.autocrlf=false ls-files</code> 不再列出该路径;</li><li>能用一句话说清 rm、add、commit 三个命令各自搬动三区域里的哪一跳。</li></ol><details><summary>要点</summary><p>原语全是现成的:<code>loadIndex</code> 读清单、过滤掉目标条目、<code>saveIndex</code> 写回。「已暂存的删除」由 <code>classifyStatus</code> 自然报出——HEAD 里有、暂存区没有、工作区还有。回查<a href="./05-index-file.html">第 5 章</a>的三态对比与<a href="./06-refs-branches.html">第 6 章</a>的 commit 流水线。</p></details>',31)])])}const u=a(r,[["render",s]]);export{f as __pageData,u as default};
